57	// One row per item type the office recognises. Base premium (what it costs to
58	// insure) and insurance value (what it is insured FOR) are independent numbers,
59	// but they are known for exactly the same set of types — so they belong in one
60	// table. Keeping them apart would leave two key sets that must agree with
61	// nothing enforcing it.
62	interface ItemSpec {
63	  basePremium: number;
64	  insuranceValue: number;
65	}
66	
67	const ITEM_SPECS = {
68	  sword: { basePremium: 100, insuranceValue: 1000 },
69	  amulet: { basePremium: 60, insuranceValue: 600 },
70	  staff: { basePremium: 80, insuranceValue: 800 },
71	  potion: { basePremium: 40, insuranceValue: 400 },
72	  rune: { basePremium: 25, insuranceValue: 250 },
73	  moonstone: { basePremium: 25, insuranceValue: 250 },
74	} as const satisfies Record<string, ItemSpec>;
75	
76	type KnownItemType = keyof typeof ITEM_SPECS;
77	
78	const isKnownItemType = (type: string): type is KnownItemType =>
79	  type in ITEM_SPECS;
80	
81	// The office insures only what its price list names. An unknown type has no
82	// premium and no insurance value, so there is nothing to quote — the whole
83	// scenario is rejected rather than priced at zero.
84	const specForItem = (item: Item): ItemSpec => {
85	  if (!isKnownItemType(item.type)) {
86	    throw new Error(`The MHPCO does not insure items of type ${item.type}`);
87	  }
88	  return ITEM_SPECS[item.type];
89	};
90	
91	const basePremiumForItem = (item: Item): number => specForItem(item).basePremium;
92	
93	const BLOCK_SIZE = 3;
94	
95	const BLOCK_BASE_PREMIUM = 60;
96	
97	const sum = (amounts: number[]): number =>
98	  amounts.reduce((total, amount) => total + amount, 0);
99	
100	// "Alike" means the same exact type, not merely the same family: two runes and
101	// a moonstone are three components but not three alike ones, so grouping them
102	// by type keeps them apart and denies them the block price.
103	const groupByType = (items: Item[]): Item[][] => {
104	  const groups = new Map<string, Item[]>();
105	  for (const item of items) {
106	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
107	  }
108	  return [...groups.values()];
109	};
110	
111	// A block is not carved out of a larger group: the block price applies only
112	// when the group consists of exactly three alike components (7 runes cost
113	// 7 × 25, not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only
114	// ever passes a single group from groupByType.
115	const basePremiumForGroup = (group: Item[]): number =>
116	  group.length === BLOCK_SIZE
117	    ? BLOCK_BASE_PREMIUM
118	    : sum(group.map(basePremiumForItem));
119	
120	const basePremiumForItems = (items: Item[]): number =>
121	  sum(groupByType(items).map(basePremiumForGroup));
122	
123	const CURSE_SURCHARGE = 0.5;
124	
125	// Every modifier is an additive percentage of its OWN base — modifiers never
126	// compound with each other. Item-scoped modifiers take the affected item's base
127	// premium as their base; policy-scoped modifiers take the policy base premium
128	// (the sum of all item base premiums). So the total is always
129	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
130	const modifierAmount = (rate: number, base: number): number => rate * base;
131	
132	const ENCHANTMENT_SURCHARGE = 0.3;
133	
134	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
135	
136	const isCursed = (item: Item): boolean => item.cursed === true;
137	
138	const attractsEnchantmentSurcharge = (item: Item): boolean =>
139	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL;
140	
141	interface ItemModifier {
142	  rate: number;
143	  appliesTo: (item: Item) => boolean;
144	}
145	
146	// Each item-scoped modifier is a row: a rate and the condition under which it
147	// applies. The predicate names the modifier, so a row needs no separate label.
148	// Adding a modifier means adding a row, not a new branch.
149	const ITEM_MODIFIERS: ItemModifier[] = [
150	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
151	  { rate: ENCHANTMENT_SURCHARGE, appliesTo: attractsEnchantmentSurcharge },
152	];
153	
154	const itemModifierRates = (item: Item): number[] =>
155	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
156	    (modifier) => modifier.rate,
157	  );
158	
159	const LOYALTY_DISCOUNT = 0.2;
160	
161	const LOYALTY_THRESHOLD_YEARS = 2;
162	
163	const isLongStanding = (customer: Customer): boolean =>
164	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
165	
166	// Discounts are surcharges with the sign flipped: expressing one as a negative
167	// rate lets it flow through the same additive sum as every surcharge, with no
168	// separate subtraction step. Discount constants stay positive magnitudes and
169	// are negated here, at the point of use, so the direction is visible in the
170	// rate list rather than buried in a constant's sign.
171	const asDiscount = (rate: number): number => -rate;
172	
173	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
174	
175	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
176	
177	// Policy-scoped modifiers apply to the policy base premium. Unlike item
178	// modifiers they select on the customer and on the quote's position in the
179	// scenario rather than on an item.
180	//
181	// The initial-assessment surcharge applies to every quote: each item is treated
182	// as a first insurance regardless of customer history. The follow-up discount
183	// is what distinguishes a customer's later contracts.
184	const policyModifierRates = (
185	  customer: Customer,
186	  isFollowUpContract: boolean,
187	): number[] => [
188	  INITIAL_ASSESSMENT_SURCHARGE,
189	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
190	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
191	];
192	
193	const itemModifiersTotal = (items: Item[]): number =>
194	  sum(
195	    items.flatMap((item) =>
196	      itemModifierRates(item).map((rate) =>
197	        modifierAmount(rate, basePremiumForItem(item)),
198	      ),
199	    ),
200	  );
201	
202	const policyModifiersTotal = (
203	  policyBasePremium: number,
204	  customer: Customer,
205	  isFollowUpContract: boolean,
206	): number =>
207	  sum(
208	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
209	      modifierAmount(rate, policyBasePremium),
210	    ),
211	  );
212	
213	// All amounts are rounded to whole G in the MHPCO's favour. For a premium —
214	// money flowing to the MHPCO — its favour is upwards. The payout half of this
215	// rule rounds the other way, but no test drives payouts yet, so only the
216	// premium direction is named here.
217	const roundPremiumInMHPCOsFavour = (amount: number): number =>
218	  Math.ceil(amount);
219	
220	const quotePremium = (
221	  items: Item[],
222	  customer: Customer,
223	  isFollowUpContract: boolean,
224	): number => {
225	  const policyBasePremium = basePremiumForItems(items);
226	  return roundPremiumInMHPCOsFavour(
227	    policyBasePremium +
228	      itemModifiersTotal(items) +
229	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
230	      PROCESSING_FEE,
231	  );
232	};
233	
234	const insuranceValueForItem = (item: Item): number =>
235	  specForItem(item).insuranceValue;
236	
237	// Deliberately NOT the shape of basePremiumForItems. Both aggregate a per-item
238	// figure from ITEM_SPECS, but the premium side groups by type first so a block
239	// of three alike components can be priced as one; this side never groups. Three
240	// runes cost 60 to insure and are insured for 3 × 250 = 750. The block is a
241	// discount on the price of cover, not a reduction of the cover bought.
242	//
243	// So the near-symmetry is a false friend: factoring the two into one traversal
244	// would read as tidier and would silently make blocks shrink the insurance sum.
245	// The repetition of `sum(items.map(...))` is the price of keeping them free to
246	// diverge, and is paid on purpose.
247	const insuranceSum = (items: Item[]): number =>
248	  sum(items.map(insuranceValueForItem));
249	
250	const CAP_MULTIPLE = 2;
251	
252	// The cap is twice the insurance sum — the value the items are insured FOR, so
253	// it is computed from the items alone and never from the premium. Curses,
254	// enchantments and loyalty change what a policy costs without changing what it
255	// covers (as do blocks — see insuranceSum). Naming the relation keeps that
256	// separation visible at the one place a policy is created.
257	const capForItems = (items: Item[]): number =>
258	  CAP_MULTIPLE * insuranceSum(items);
259	
260	const DEDUCTIBLE = 100;
261	
262	interface Policy {
263	  items: Item[];
264	  remainingCap: number;
265	}
266	
267	// Steps are not independent: a quote's premium depends on how many quotes came
268	// before it, and a claim draws down the cap of a policy an earlier quote
269	// created. So a step is a function from state to (result, next state), and the
270	// scenario is a fold over that — not a map, which would promise an independence
271	// the steps do not have.
272	//
273	// Policies are keyed by the index of the quote step that created them: a claim
274	// step names its policy by that zero-based index.
275	interface ScenarioState {
276	  quotesSoFar: number;
277	  policies: Map<number, Policy>;
278	}
279	
280	const INITIAL_STATE: ScenarioState = {
281	  quotesSoFar: 0,
282	  policies: new Map(),
283	};
284	
285	interface StepOutcome {
286	  result: StepResult;
287	  state: ScenarioState;
288	}
289	
290	// Both operations end by filing a policy under its quote's index — a claim
291	// re-files the same policy with a drawn-down cap. Naming that once keeps the
292	// Map out of the operations, so neither has to know how policies are stored.
293	const withPolicy = (
294	  state: ScenarioState,
295	  policyIndex: number,
296	  policy: Policy,
297	): ScenarioState => ({
298	  ...state,
299	  policies: new Map(state.policies).set(policyIndex, policy),
300	});
301	
302	const runQuote = (
303	  step: QuoteStep,
304	  customer: Customer,
305	  state: ScenarioState,
306	  stepIndex: number,
307	): StepOutcome => ({
308	  result: {
309	    premium: quotePremium(step.items, customer, state.quotesSoFar > 0),
310	  },
311	  state: withPolicy(
312	    { ...state, quotesSoFar: state.quotesSoFar + 1 },
313	    stepIndex,
314	    {
315	      items: step.items,
316	      remainingCap: capForItems(step.items),
317	    },
318	  ),
319	});
320	
321	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
322	
323	const REDUCED_REIMBURSEMENT_RATE = 0.5;
324	
325	const FULL_REIMBURSEMENT_RATE = 1;
326	
327	// Reads enchantment like the premium-side surcharge rule, but is a different
328	// rule with its own level: this one halves what a claim pays out, that one
329	// raises what a policy costs. Sharing a predicate would tie two levels that the
330	// spec lets move independently, so the shape is repeated deliberately.
331	const qualifiesForReducedReimbursement = (item: Item): boolean =>
332	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
333	
334	// The reimbursement rate is decided first, then one deductible comes off.
335	//
336	// The dragon-material clause is absent on purpose, not by oversight. It promises
337	// full reimbursement of the damage before the deductible — which is exactly what
338	// FULL_REIMBURSEMENT_RATE already gives every item that misses the reduced-rate
339	// clause. Where both clauses apply the spec awards it to the 50 % rule. Between
340	// them the two facts leave the clause with no input it can move: dragon material
341	// at enchantment 9 or 8 pays the same 400 as steel at those levels, and at
342	// enchantment 5 it pays the same 700 steel would. Writing it as its own branch
343	// would add a branch no test could ever tell from the default — a distinction
344	// the domain does not make.
345	const reimbursementRate = (item: Item): number =>
346	  qualifiesForReducedReimbursement(item)
347	    ? REDUCED_REIMBURSEMENT_RATE
348	    : FULL_REIMBURSEMENT_RATE;
349	
350	const payoutForDamage = (damage: Damage, item: Item): number =>
351	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
352	
353	// Returns AN insured item of the damaged type, not THE damaged one — a policy
354	// can cover two swords, so the type does not name a unique item. Two damage
355	// entries of the same type are both answered with the same first match.
356	//
357	// That is sound today because the answer is used solely to read payout
358	// attributes (the reimbursement rate), and the covered case — two damages
359	// against two swords — insures identical swords, which read the same either
360	// way. The deductible is charged per damage entry, not per matched item, so
361	// counting is unaffected too.
362	//
363	// One thing would break it, not yet under test: two swords with DIFFERENT
364	// attributes (say enchantment 3 and 9). Both damages would take the first
365	// sword's rate; the second should take its own. This lookup must then become a
366	// pairing that consumes what it matches. The honest name marks that spot.
367	//
368	// The `!` is a proof, not an assumption: rejectUnmatchedDamages runs first and
369	// throws unless every claimed type is covered at least as many times as it is
370	// named — so by the time this runs, a match exists for every damage entry. Both
371	// ways it could fail are covered by tests: claiming a type more often than it is
372	// insured, and claiming a type the policy does not cover at all.
373	const anInsuredItemOfDamagedType = (policy: Policy, damage: Damage): Item =>
374	  policy.items.find((item) => item.type === damage.itemType)!;
375	
376	// Counts how many times each value occurs. Deliberately typed on strings rather
377	// than on Item: the guard below tallies two different things (item types held
378	// and item types named by damages) and only their counts are ever compared, so
379	// the tally has no business knowing what the strings mean.
380	const tally = (values: string[]): Map<string, number> => {
381	  const counts = new Map<string, number>();
382	  for (const value of values) {
383	    counts.set(value, (counts.get(value) ?? 0) + 1);
384	  }
385	  return counts;
386	};
387	
388	// Every damage entry must claim an insured item of its own, so a type cannot be
389	// damaged more times than the policy covers it. One rule, two error cases the
390	// spec states separately: claiming a type more often than it is insured, and
391	// claiming a type the policy does not cover at all. The second is the first at
392	// zero — an uninsured type is covered 0 times against a claimed 1 — so both are
393	// caught by the same comparison rather than by a separate membership test.
394	//
395	// Checked before any payout is computed: the spec rejects the whole claim, not
396	// just the surplus entries.
397	const rejectUnmatchedDamages = (policy: Policy, incident: Incident): void => {
398	  const insured = tally(policy.items.map((item) => item.type));
399	  const claimed = tally(incident.damages.map((damage) => damage.itemType));
400	  for (const [type, claimedCount] of claimed) {
401	    const insuredCount = insured.get(type) ?? 0;
402	    if (claimedCount > insuredCount) {
403	      throw new Error(
404	        `Policy covers ${insuredCount} ${type}(s) but the claim names ${claimedCount}`,
405	      );
406	    }
407	  }
408	};
409	
410	// A damage is what an incident cost the owner, so it cannot be negative. Zero
411	// is left alone: the spec forbids only negative amounts, and a zero damage
412	// simply pays nothing once the deductible bites.
413	const isNegative = (damage: Damage): boolean => damage.amount < 0;
414	
415	const rejectNegativeDamages = (incident: Incident): void => {
416	  const negative = incident.damages.find(isNegative);
417	  if (negative) {
418	    throw new Error(
419	      `Damage to ${negative.itemType} is negative: ${negative.amount}`,
420	    );
421	  }
422	};
423	
424	// Both guards run before any payout is computed: the spec rejects the whole
425	// claim, not just the offending entries, so a valid entry alongside an invalid
426	// one must not be paid.
427	//
428	// They are two statements rather than a list of validations. Their signatures
429	// differ (only the first needs the policy), so a uniform list could hold them
430	// only by giving the second a parameter it ignores. And the order is not
431	// incidental: rejectUnmatchedDamages must come first because it is what makes
432	// the lookup in anInsuredItemOfDamagedType total — an obligation that reads as
433	// a sequenced line here but would vanish into array order in a list. The third
434	// validation the spec calls for (unknown item type) belongs to the quote path,
435	// so this pair is closed at two and has no growth to abstract over.
436	const payoutForIncident = (policy: Policy, incident: Incident): number => {
437	  rejectUnmatchedDamages(policy, incident);
438	  rejectNegativeDamages(incident);
439	  return sum(
440	    incident.damages.map((damage) =>
441	      payoutForDamage(damage, anInsuredItemOfDamagedType(policy, damage)),
442	    ),
443	  );
444	};
445	
446	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
447	  // A claim naming a policy that does not exist is a spec error case, but no
448	  // test drives it yet. The assertion stands in until one does — at which point
449	  // the missing case becomes the error branch rather than a crash.
450	  const policy = state.policies.get(step.policy)!;
451	  const payout = payoutForIncident(policy, step.incident);
452	  const remainingCap = policy.remainingCap - payout;
453	  return {
454	    result: { payout, remainingCap },
455	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
456	  };
457	};
458	
459	// Dispatch decides once what a step is; each operation then owns both its
460	// result and how it advances the state, so no caller has to re-test step.op to
461	// know what the step did.
462	const runStep = (
463	  step: Step,
464	  customer: Customer,
465	  state: ScenarioState,
466	  stepIndex: number,
467	): StepOutcome =>
468	  step.op === "quote"
469	    ? runQuote(step, customer, state, stepIndex)
470	    : runClaim(step, state);
471	
472	// The fold carries both halves of the outcome: the results accumulated so far
473	// and the state the next step will see. Threading the state explicitly (rather
474	// than recovering it from the last result) keeps the dependency between steps
475	// visible in the type.
476	interface ScenarioRun {
477	  results: StepResult[];
478	  state: ScenarioState;
479	}
480	
481	const INITIAL_RUN: ScenarioRun = { results: [], state: INITIAL_STATE };
482	
483	const appendStep =
484	  (customer: Customer) =>
485	  (run: ScenarioRun, step: Step, stepIndex: number): ScenarioRun => {
486	    const outcome = runStep(step, customer, run.state, stepIndex);
487	    return {
488	      results: [...run.results, outcome.result],
489	      state: outcome.state,
490	    };
491	  };
492	
493	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
494	  results: steps.reduce(appendStep(customer), INITIAL_RUN).results,
495	});
